1	package theme
2	
3	import (
4		"image/color"
5		"testing"
6	)
7	
8	// DEVDESK-764: every text colour of the palette reaches WCAG 1.4.3 (4.5:1) on
9	// the surface it is really painted on, on each of the 13 shipped themes. The
10	// measure of 2026-11-23 (docs/measurements/2026-11-23-sec-detail-contrast.md)
11	// found ColorDim, ColorSubTitleFg, ColorWarn and ColorFooterError below it.
12	//
13	// Surfaces, and why each colour is measured on the ones it has:
14	//
15	//   - background: ColorBackground, under everything (Rule 115).
16	//   - selected row: ColorTableLineSelected. A plain "normal" selection keeps
17	//     every cell's own foreground and repaints this background under it
18	//     (Rule 118, Rule 122), so any colour a table cell can take is read on it.
19	//   - raised surface: ColorCmdLineBg, which the chart, the inactive tab and the
20	//     disabled button sit on. It is the same hex as the selected row on every
21	//     shipped theme, but it is its own key, so it is measured on its own.
22	//
23	// ColorSubTitleFg only heads a block of text on the background. The footer
24	// colours are text on the background (the footer line); under the cursor they
25	// are the activity dot and the severity icon, a glyph held to 3:1 (WCAG 1.4.11).
26	const (
27		textMinContrast  = 4.5 // WCAG 1.4.3, text
28		glyphMinContrast = 3.0 // WCAG 1.4.11, graphical object
29	)
30	
31	type textInk struct {
32		what string
33		// key is the theme-file key that sets the colour ("" for a closed alias),
34		// read by TestSuggestTones only.
35		key string
36		fg  func() color.Color
37		// on lists the surfaces the colour is painted on and the ratio each needs.
38		on []surfaceNeed
39	}
40	
41	type surfaceNeed struct {
42		surface string
43		bg      func() color.Color
44		min     float64
45	}
46	
47	var (
48		onBackground = func(min float64) surfaceNeed {
49			return surfaceNeed{"ColorBackground", func() color.Color { return ColorBackground }, min}
50		}
51		onSelectedRow = func(min float64) surfaceNeed {
52			return surfaceNeed{"ColorTableLineSelected", func() color.Color { return ColorTableLineSelected }, min}
53		}
54		onRaised = func(min float64) surfaceNeed {
55			return surfaceNeed{"ColorCmdLineBg", func() color.Color { return ColorCmdLineBg }, min}
56		}
57	)
58	
59	// DEVDESK-770 part A: the colours the 2026-11-24 measure left under the bar.
60	// ColorSecondary is the header keys, the table header, the active-tab background
61	// and the activity dot, the update mark and the icons (a glyph, 3:1 on the
62	// selected row); ColorTableHeaderFg, ColorPrimary, ColorTitleFg and
63	// ColorAppTitleFg are text on the background. ColorViewportBorder is the frame
64	// border: a non-text object, 3:1 (WCAG 1.4.11) on the background it is drawn on
65	// (it falls back to ColorBorder, which is never painted on its own).
66	func textInks() []textInk {
67		allSurfaces := []surfaceNeed{onBackground(textMinContrast), onSelectedRow(textMinContrast), onRaised(textMinContrast)}
68		return []textInk{
69			{"ColorText", "color_text", func() color.Color { return ColorText }, allSurfaces},
70			{"ColorDim", "color_dim", func() color.Color { return ColorDim }, allSurfaces},
71			{"ColorSubTitleFg", "subtitle_fg", func() color.Color { return ColorSubTitleFg },
72				[]surfaceNeed{onBackground(textMinContrast)}},
73			{"ColorWarn", "color_warn", func() color.Color { return ColorWarn },
74				[]surfaceNeed{onBackground(textMinContrast), onSelectedRow(textMinContrast)}},
75			{"ColorFooterWarn", "severity_medium", func() color.Color { return ColorFooterWarn },
76				[]surfaceNeed{onBackground(textMinContrast), onSelectedRow(glyphMinContrast)}},
77			{"ColorFooterError", "severity_critical", func() color.Color { return ColorFooterError },
78				[]surfaceNeed{onBackground(textMinContrast), onSelectedRow(glyphMinContrast)}},
79			{"ColorSecondary", "color_secondary", func() color.Color { return ColorSecondary },
80				[]surfaceNeed{onBackground(textMinContrast), onSelectedRow(glyphMinContrast)}},
81			{"ColorTableHeaderFg", "table_header_fg", func() color.Color { return ColorTableHeaderFg },
82				[]surfaceNeed{onBackground(textMinContrast)}},
83			{"ColorPrimary", "color_primary", func() color.Color { return ColorPrimary },
84				[]surfaceNeed{onBackground(textMinContrast)}},
85			{"ColorTitleFg", "title_fg", func() color.Color { return ColorTitleFg },
86				[]surfaceNeed{onBackground(textMinContrast)}},
87			{"ColorAppTitleFg", "app_title_fg", func() color.Color { return ColorAppTitleFg },
88				[]surfaceNeed{onBackground(textMinContrast)}},
89			// DEVDESK-770 part B (D181): the HIGH and LOW badge backgrounds. As a
90			// colour they are painted on the background and, under the cursor, on the
91			// selected row, where a glyph is held to 3:1 (Rule 118). The badge text is
92			// ColorBackground, so the 4.5:1 here is also the badge's own ratio.
93			{"ColorSeverityHigh", "severity_high", func() color.Color { return ColorSeverityHigh },
94				[]surfaceNeed{onBackground(textMinContrast), onSelectedRow(glyphMinContrast)}},
95			{"ColorSeverityLow", "severity_low", func() color.Color { return ColorSeverityLow },
96				[]surfaceNeed{onBackground(textMinContrast), onSelectedRow(glyphMinContrast)}},
97			{"ColorViewportBorder (frame border, non-text)", "viewport_border", func() color.Color { return ColorViewportBorder },
98				[]surfaceNeed{onBackground(glyphMinContrast)}},
99		}
100	}
101	
102	// textPair is a foreground painted on a background that is not one of the
103	// shared surfaces: both come from the same component.
104	type textPair struct {
105		what         string
106		fgKey, bgKey string
107		min          float64
108		get          func() (fg, bg color.Color)
109	}
110	
111	func styleColours(focused bool, variant string) func() (color.Color, color.Color) {
112		return func() (color.Color, color.Color) {
113			s := ButtonStyle(focused, variant)
114			return s.GetForeground(), s.GetBackground()
115		}
116	}
117	
118	// DEVDESK-770 part A. The four severity badges are held by
119	// TestEverySeverityBadgeReachesTextContrastOnEveryTheme (part B).
120	func textPairs() []textPair {
121		return []textPair{
122			{"active tab (ColorTabActiveFg on ColorTabActiveBg)", "tab_active_fg", "tab_active_bg", textMinContrast,
123				func() (color.Color, color.Color) { return ColorTabActiveFg, ColorTabActiveBg }},
124			{"primary button, focused", "button_fg", "button_bg", textMinContrast, styleColours(true, "primary")},
125			{"primary button, unfocused", "button_inactive_fg", "button_inactive_bg", textMinContrast, styleColours(false, "primary")},
126			{"secondary button, unfocused", "button_inactive_fg", "button_inactive_bg", textMinContrast, styleColours(false, "secondary")},
127			{"command line, inactive (ColorCmdLineInactiveFg on ColorCmdLineBg)", "cmd_line_inactive_fg", "cmd_line_bg", textMinContrast,
128				func() (color.Color, color.Color) { return ColorCmdLineInactiveFg, ColorCmdLineBg }},
129		}
130	}
131	
132	// Each failure names the theme, the colour, the surface and the measured ratio.
133	func TestEveryTextColourReachesItsContrastOnEveryTheme(t *testing.T) {
134		eachShippedTheme(t, func(t *testing.T, name string) {
135			for _, ink := range textInks() {
136				for _, need := range ink.on {
137					fg, bg := ink.fg(), need.bg()
138					ratio, err := ContrastRatio(fg, bg)
139					if err != nil {
140						t.Errorf("theme %s: %s on %s: %v", name, ink.what, need.surface, err)
141						continue
142					}
143					if ratio < need.min {
144						t.Errorf("theme %s: %s %s on %s %s is %.2f:1, want >= %.1f:1",
145							name, ink.what, Hex(fg), need.surface, Hex(bg), ratio, need.min)
146					}
147				}
148			}
149		})
150	}
151	
152	// Each failure names the theme, the pair, both colours and the measured ratio.
153	func TestEveryTextPairReachesItsContrastOnEveryTheme(t *testing.T) {
154		eachShippedTheme(t, func(t *testing.T, name string) {
155			for _, p := range textPairs() {
156				fg, bg := p.get()
157				ratio, err := ContrastRatio(fg, bg)
158				if err != nil {
159					t.Errorf("theme %s: %s: %v", name, p.what, err)
160					continue
161				}
162				if ratio < p.min {
163					t.Errorf("theme %s: %s, %s on %s is %.2f:1, want >= %.1f:1",
164						name, p.what, Hex(fg), Hex(bg), ratio, p.min)
165				}
166			}
167		})
168	}
169	
170	// A greyed control still has to be read: raising ColorDim is not enough when the
171	// label sits on a background of the same hue. The disabled button used to paint
172	// ColorDim on ColorButtonInactiveBg, which is the same hex on nine themes (1:1).
173	func TestTheDisabledButtonLabelReachesTextContrastOnEveryTheme(t *testing.T) {
174		eachShippedTheme(t, func(t *testing.T, name string) {
175			for _, focused := range []bool{false, true} {
176				s := ButtonStyle(focused, "disabled")
177				fg, bg := s.GetForeground(), s.GetBackground()
178				ratio, err := ContrastRatio(fg, bg)
179				if err != nil {
180					t.Errorf("theme %s: disabled button (focused=%v): %v", name, focused, err)
181					continue
182				}
183				if ratio < textMinContrast {
184					t.Errorf("theme %s: disabled button (focused=%v) label %s on %s is %.2f:1, want >= %.1f:1",
185						name, focused, Hex(fg), Hex(bg), ratio, textMinContrast)
186				}
187			}
188		})
189	}
190	
191	// Grey says "not now", and colour alone must not be the only thing that says it
192	// (WCAG 1.4.1): a disabled button is italic, an enabled one is not, and the
193	// focus mark of a disabled button is an inversion rather than a colour only.
194	func TestTheDisabledButtonDiffersFromAnEnabledOneByMoreThanColour(t *testing.T) {
195		withTheme(t, DefaultTheme())
196		for _, focused := range []bool{false, true} {
197			dis, en := ButtonStyle(focused, "disabled"), ButtonStyle(focused, "primary")
198			if !dis.GetItalic() {
199				t.Errorf("focused=%v: the disabled button is not italic", focused)
200			}
201			if en.GetItalic() {
202				t.Errorf("focused=%v: the enabled button is italic: the signal would carry nothing", focused)
203			}
204		}
205		if on, off := ButtonStyle(true, "disabled"), ButtonStyle(false, "disabled"); sameColor(on.GetBackground(), off.GetBackground()) {
206			t.Error("a focused disabled button keeps the unfocused background: the focus would be invisible")
207		}
208	}
209	
210	// Rule 118: an inactive tab is ColorDim on the tab's own background. The theme
211	// files used to set tab_inactive_fg on its own, to a tone that was never held to
212	// 4.5:1 (1.4:1 on catppuccin-latte).
213	func TestTheInactiveTabLabelReachesTextContrastOnEveryTheme(t *testing.T) {
214		eachShippedTheme(t, func(t *testing.T, name string) {
215			ratio, err := ContrastRatio(ColorTabInactiveFg, ColorTabInactiveBg)
216			if err != nil {
217				t.Fatal(err)
218			}
219			if ratio < textMinContrast {
220				t.Errorf("theme %s: ColorTabInactiveFg %s on ColorTabInactiveBg %s is %.2f:1, want >= %.1f:1",
221					name, Hex(ColorTabInactiveFg), Hex(ColorTabInactiveBg), ratio, textMinContrast)
222			}
223		})
224	}
225	
226	// severityLevels are the four levels a badge exists for. INFO and UNKNOWN share
227	// a muted badge that is not part of this decision (D179, "Not decided here").
228	var severityLevels = []string{"CRITICAL", "HIGH", "MEDIUM", "LOW"}
229	
230	// DEVDESK-770 part B (D181). A severity badge is the selected row of a finding
231	// of that level: TableStylesForSeverity(level).Selected paints the level's
232	// foreground on the level's background. The ratio is read from the style the
233	// table really uses, so a badge cannot pass on a pair the screen never shows.
234	// Each failure names the theme, the level, both colours and the ratio.
235	func TestEverySeverityBadgeReachesTextContrastOnEveryTheme(t *testing.T) {
236		eachShippedTheme(t, func(t *testing.T, name string) {
237			for _, level := range severityLevels {
238				sel := TableStylesForSeverity(level).Selected
239				fg, bg := sel.GetForeground(), sel.GetBackground()
240				ratio, err := ContrastRatio(fg, bg)
241				if err != nil {
242					t.Errorf("theme %s: %s badge: %v", name, level, err)
243					continue
244				}
245				if ratio < textMinContrast {
246					t.Errorf("theme %s: %s badge, %s on %s is %.2f:1, want >= %.1f:1",
247						name, level, Hex(fg), Hex(bg), ratio, textMinContrast)
248				}
249			}
250			// ColorFooterError and ColorFooterWarn alias the CRITICAL and MEDIUM badge
251			// backgrounds, so the badge foregrounds have to read on them too.
252			aliased := []struct {
253				what   string
254				fg, bg color.Color
255			}{
256				{"CRITICAL badge (ColorSeverityCriticalFg on ColorFooterError)", ColorSeverityCriticalFg, ColorFooterError},
257				{"MEDIUM badge (ColorSeverityMediumFg on ColorFooterWarn)", ColorSeverityMediumFg, ColorFooterWarn},
258			}
259			for _, p := range aliased {
260				ratio, err := ContrastRatio(p.fg, p.bg)
261				if err != nil {
262					t.Errorf("theme %s: %s: %v", name, p.what, err)
263					continue
264				}
265				if ratio < textMinContrast {
266					t.Errorf("theme %s: %s, %s on %s is %.2f:1, want >= %.1f:1",
267						name, p.what, Hex(p.fg), Hex(p.bg), ratio, textMinContrast)
268				}
269			}
270		})
271	}
272	
273	// The text of a badge is the application background, on every level and every
274	// theme: a light badge carries dark text and a dark one light text, which is
275	// what CRITICAL and MEDIUM already do. It makes the foreground follow the
276	// theme's own surface instead of a tone nobody holds to a ratio, and it leaves
277	// one number to move per badge (its background). INFO is left out: its badge is
278	// not part of D181.
279	func TestSeverityBadgeTextIsTheAppBackgroundOnEveryTheme(t *testing.T) {
280		eachShippedTheme(t, func(t *testing.T, name string) {
281			badges := []struct {
282				level string
283				fg    color.Color
284			}{
285				{"CRITICAL", ColorSeverityCriticalFg},
286				{"HIGH", ColorSeverityHighFg},
287				{"MEDIUM", ColorSeverityMediumFg},
288				{"LOW", ColorSeverityLowFg},
289			}
290			for _, b := range badges {
291				if Hex(b.fg) != Hex(ColorBackground) {
292					t.Errorf("theme %s: %s badge text is %s, want ColorBackground %s",
293						name, b.level, Hex(b.fg), Hex(ColorBackground))
294				}
295			}
296		})
297	}
298	
299	// minSeverityGap is the smallest CIE76 distance CRITICAL and HIGH keep on a
300	// shipped theme. Measured on 2026-11-24 before part B: the closest pair is
301	// catppuccin-macchiato at 8.9 (frappe 11.3, latte 11.7, mocha and default
302	// 14.1); raising HIGH to 4.5:1 moves latte from 11.7 to 9.0 and leaves the
303	// others within 1.6 of their value. The bar is 8, a little under the tightest
304	// measured pair: it catches a HIGH pulled onto CRITICAL to reach a contrast,
305	// not the palettes' own closeness, and the word on the badge (see
306	// TestTheSeverityCellSpellsTheLevelOut) is the other carrier.
307	const minSeverityGap = 8.0
308	
309	func TestSeverityHighAndCriticalStayApart(t *testing.T) {
310		eachShippedTheme(t, func(t *testing.T, name string) {
311			d, err := ColorDistance(ColorSeverityCritical, ColorSeverityHigh)
312			if err != nil {
313				t.Fatal(err)
314			}
315			if d < minSeverityGap {
316				t.Errorf("theme %s: CRITICAL %s and HIGH %s are delta E %.1f apart, want >= %.1f",
317					name, Hex(ColorSeverityCritical), Hex(ColorSeverityHigh), d, minSeverityGap)
318			}
319		})
320	}
321	
322	// A theme written before severity_low existed, or by hand, may leave both LOW
323	// keys out. The fallback pair has to stay readable. Since D181 the fallbacks are
324	// ColorDim for the background and ColorBackground for the text, the same pair a
325	// shipped dark theme sets: ColorDim is held to 4.5:1 on the background, so the
326	// pair reads on every theme. (D177 had ColorCmdLineBg and ColorText, because
327	// ColorDim was then a light text tone under a light ColorText, about 2:1.)
328	func TestAThemeWithoutSeverityLowKeepsAReadableLowBadge(t *testing.T) {
329		for name, th := range shippedThemes(t) {
330			t.Run(name, func(t *testing.T) {
331				bare := *th
332				bare.SeverityLow, bare.SeverityLowFg = "", ""
333				withTheme(t, &bare)
334				ratio, err := ContrastRatio(ColorSeverityLowFg, ColorSeverityLow)
335				if err != nil {
336					t.Fatal(err)
337				}
338				if ratio < textMinContrast {
339					t.Errorf("theme %s without severity_low: %s on %s is %.2f:1, want >= %.1f:1",
340						name, Hex(ColorSeverityLowFg), Hex(ColorSeverityLow), ratio, textMinContrast)
341				}
342			})
343		}
344	}
345	
346	// The fallbacks themselves: a theme that omits the two LOW keys gets ColorDim
347	// under ColorBackground, not the pre-D181 ColorCmdLineBg under ColorText.
348	func REDACTED(t *testing.T) {
349		for name, th := range shippedThemes(t) {
350			t.Run(name, func(t *testing.T) {
351				bare := *th
352				bare.SeverityLow, bare.SeverityLowFg = "", ""
353				withTheme(t, &bare)
354				if Hex(ColorSeverityLow) != Hex(ColorDim) {
355					t.Errorf("theme %s without severity_low: LOW badge is %s, want ColorDim %s",
356						name, Hex(ColorSeverityLow), Hex(ColorDim))
357				}
358				if Hex(ColorSeverityLowFg) != Hex(ColorBackground) {
359					t.Errorf("theme %s without severity_low_fg: LOW badge text is %s, want ColorBackground %s",
360						name, Hex(ColorSeverityLowFg), Hex(ColorBackground))
361				}
362			})
363		}
364	}
