195	func TestMinimalTone(t *testing.T) {
196		darkBg := rgb(30, 30, 46)
197		darkBg2 := rgb(49, 50, 68)
198		lightBg := rgb(239, 241, 245)
199		cases := []struct {
200			name     string
201			fg       color.Color
202			bgs      []color.Color
203			min      float64
204			wantErr  bool
205			wantSame bool
206			wantDir  int // +1 lighter, -1 darker, 0 unchecked
207		}{
208			{"already passes", rgb(205, 214, 244), []color.Color{darkBg}, 4.5, false, true, 0},
209			{"dark surface lightens", rgb(88, 91, 112), []color.Color{darkBg, darkBg2}, 4.5, false, false, +1},
210			{"light surface darkens", rgb(172, 176, 190), []color.Color{lightBg}, 4.5, false, false, -1},
211			{"saturated on dark", rgb(40, 60, 190), []color.Color{darkBg}, 4.5, false, false, +1},
212			{"saturated on light", rgb(250, 140, 60), []color.Color{lightBg}, 4.5, false, false, -1},
213			{"two surfaces at once", rgb(120, 125, 150), []color.Color{darkBg, darkBg2}, 4.5, false, false, +1},
214			{"impossible on black and white", rgb(128, 128, 128), []color.Color{rgb(0, 0, 0), rgb(255, 255, 255)}, 5, true, false, 0},
215			{"impossible ratio", rgb(128, 128, 128), []color.Color{darkBg}, 22, true, false, 0},
216		}
217		for _, c := range cases {
218			t.Run(c.name, func(t *testing.T) {
219				got, de, err := minimalTone(c.fg, c.bgs, c.min)
220				if c.wantErr {
221					if !errors.Is(err, errToneUnreachable) {
222						t.Fatalf("err = %v, want errToneUnreachable (got %v, ΔE %.2f)", err, got, de)
223					}
224					return
225				}
226				if err != nil {
227					t.Fatal(err)
228				}
229				if c.wantSame {
230					if got != c.fg || de != 0 {
231						t.Errorf("a colour that passes moved: %s -> %s, ΔE %.2f", Hex(c.fg), Hex(got), de)
232					}
233					return
234				}
235				for _, bg := range c.bgs {
236					if r, _ := ContrastRatio(got, bg); r < c.min {
237						t.Errorf("%s on %s is %.2f:1, want >= %.1f:1", Hex(got), Hex(bg), r, c.min)
238					}
239				}
240				h0, _, l0, _ := toHSL(c.fg)
241				h1, _, l1, _ := toHSL(got)
242				if c.wantDir > 0 && l1 <= l0 || c.wantDir < 0 && l1 >= l0 {
243					t.Errorf("lightness %.3f -> %.3f, want it to go %+d", l0, l1, c.wantDir)
244				}
245				if g := hueGap(h0, h1); g > 1 {
246					t.Errorf("hue moved by %.2f degrees (%s -> %s), want <= 1", g, Hex(c.fg), Hex(got))
247				}
248				if de <= 0 {
249					t.Errorf("ΔE = %.2f for a colour that moved", de)
250				}
251			})
252		}
253	}
