308	// themeKeyState tells where a theme file keeps a key: its value when it is
309	// written, "fallback" when the key is absent and the colour comes from another.
310	func themeKeyState(th *Theme, key string) string {
311		if key == "" {
312			return "no key (alias)"
313		}
314		v := reflect.ValueOf(th).Elem()
315		for i := 0; i < v.NumField(); i++ {
316			tag, _, _ := strings.Cut(v.Type().Field(i).Tag.Get("json"), ",")
317			if tag == key {
318				if s := v.Field(i).String(); s != "" {
319					return "explicit " + s
320				}
321				return "fallback (key absent: add it)"
322			}
323		}
324		return "unknown key"
325	}
