func TestPaletteBorderIsAClosedAliasOfPrimary(t *testing.T) {
	eachShippedTheme(t, func(t *testing.T, name string) {
		if ColorPaletteBorder != ColorPrimary {
	t.SeverityCritical = "#aa0011"
	t.SeverityMedium = "#aa8811"
